 "content": "def transform(grid):
    """Copy the colored pattern around its 5 anchor to the other 5 marker."""
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 5]
    if len(markers) < 2:
        return out

    # The anchor embedded in the pattern has nearby non-background cells;
    # the destination marker is isolated.
    def nearby_count(anchor):
        ar, ac = anchor
        return sum(
            1 for r, row in enumerate(grid) for c, v in enumerate(row)
            if v not in (0, 5) and max(abs(r - ar), abs(c - ac)) <= 4
        )

    source = max(markers, key=nearby_count)
    target = min((p for p in markers if p != source), key=nearby_count)
    sr, sc = source
    tr, tc = target
    dr, dc = tr - sr, tc - sc

    # The target 5 is a placement marker, not part of the copied pattern.
    out[tr][tc] = 0
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value in (0, 5):
                continue
            rr, cc = r + dr, c + dc
            if 0 <= rr < len(grid) and 0 <= cc < len(row):
                out[rr][cc] = value
    return out
